import { vi } from "vitest";
import { runInNewContext } from "node:vm";
import {
  H3,
  HTTPError,
  bodyLimit,
  readBody,
  readValidatedBody,
  requireBasicAuth,
  type H3Event,
} from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("errors", (t, { it, expect, describe }) => {
  const consoleMock = ((globalThis.console.error as any) = vi.fn());

  describe("error response bodies", () => {
    for (const withOnError of [false, true]) {
      const hook = withOnError ? "with onError" : "without onError";

      it(`omits the body for a missing HEAD route ${hook}`, async () => {
        if (!withOnError) t.app.config.onError = undefined;
        const res = await t.fetch("/missing", { method: "HEAD" });
        expect(res.status).toBe(404);
        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
        expect(res.headers.get("content-length")).toBeNull();
        expect(await res.text()).toBe("");
        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
      });

      for (const asyncHandler of [false, true]) {
        for (const method of ["GET", "HEAD"]) {
          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
            if (!withOnError) t.app.config.onError = undefined;
            const handler = (event: H3Event) => {
              event.res.headers.set("x-success", "success");
              event.res.errHeaders.set("x-error", "prepared");
              event.res.errHeaders.append("set-cookie", "prepared=1");
              throw new HTTPError({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
                headers: { "x-error-own": "own", "set-cookie": "error=1" },
              });
            };
            t.app.use(asyncHandler ? async (event) => handler(event) : handler);

            const res = await t.fetch("/", { method });
            expect(res.status).toBe(422);
            expect(res.statusText).toBe("Unprocessable");
            expect(res.headers.get("content-type")).toBe("application/problem+json;charset=UTF-8");
            expect(res.headers.get("x-error")).toBe("prepared");
            expect(res.headers.get("x-error-own")).toBe("own");
            expect(res.headers.get("x-success")).toBeNull();
            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
            if (method === "HEAD") {
              expect(res.headers.get("content-length")).toBeNull();
              expect(await res.text()).toBe("");
            } else {
              expect(await res.json()).toMatchObject({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
              });
            }
            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
          });
        }
      }
    }
  });

  it("throw HTTPError", async () => {
    t.app.use(() => {
      throw new HTTPError({
        statusText: "Unprocessable",
        status: 422,
        data: { test: 123 },
        body: { topLevel: "works" },
      });
    });
    const result = await t.fetch("/");
    expect(result.status).toBe(422);
    expect(result.statusText).toBe("Unprocessable");
    expect(await result.json()).toMatchObject({
      status: 422,
      statusText: "Unprocessable",
      message: "Unprocessable",
      data: { test: 123 },
      topLevel: "works",
    });
  });

  it("return HTTPError", async () => {
    t.app.use(() => {
      return new HTTPError({
        statusText: "Unprocessable",
        status: 422,
        data: { test: 123 },
      });
    });
    const result = await t.fetch("/");
    expect(result.status).toBe(422);
    expect(result.statusText).toBe("Unprocessable");
    expect(await result.json()).toMatchObject({
      status: 422,
      statusText: "Unprocessable",
      message: "Unprocessable",
      data: { test: 123 },
    });
  });

  it("unandled errors", async () => {
    t.app.use("/api/test", () => {
      // @ts-expect-error
      foo.bar = 123;
    });
    const result = await t.fetch("/api/test");

    expect(t.errors[0].message).toMatch("foo is not defined");
    expect(t.errors[0].unhandled).toBe(true);
    t.errors = [];

    expect(result.status).toBe(500);
    expect(JSON.parse(await result.text())).toMatchObject({
      status: 500,
    });
  });

  it("can send runtime error", async () => {
    consoleMock.mockReset();

    t.app.get("/api/test", () => {
      throw new HTTPError({
        status: 400,
        statusText: "Bad Request",
        data: {
          message: "Invalid Input",
        },
      });
    });

    const result = await t.fetch("/api/test");

    expect(result.status).toBe(400);
    expect(result.headers.get("content-type")).toMatch("application/problem+json");

    expect(console.error).not.toBeCalled();

    expect(JSON.parse(await result.text())).toMatchObject({
      status: 400,
      statusText: "Bad Request",
      data: {
        message: "Invalid Input",
      },
    });
  });

  it("can access original error", async () => {
    class CustomError extends Error {
      customError = true;
    }

    t.app.get("/", () => {
      throw new HTTPError(new CustomError());
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(500);

    expect(t.errors[0].cause).toBeInstanceOf(CustomError);
  });

  it("can inherit from cause", async () => {
    class CustomError extends Error {
      override cause = new HTTPError({
        status: 400,
        statusText: "Bad Request",
        unhandled: true,
      });
    }

    t.app.get("/", () => {
      throw new HTTPError(new CustomError());
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(400);
    expect(t.errors[0].unhandled).toBe(true);

    t.errors = [];
  });

  it("can inherit deprecated statusCode/statusMessage from cause", async () => {
    const cause = { statusCode: 404, statusMessage: "Not Found" };

    t.app.get("/", () => {
      throw new HTTPError({ cause });
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(404);
    expect(res.statusText).toBe("Not Found");

    t.errors = [];
  });

  it("error headers", async () => {
    t.app.config.onError = async (error, event) => {
      const headers = new Headers(event.res.headers);
      headers.set("set-cookie", "error=1");
      return new Response(error.toString(), { status: 501, headers });
    };

    t.app.get("/", async (event) => {
      event.res.headers.set("set-cookie", "auth=1");
      event.res.headers.set("x-test", "1");
      throw new HTTPError("test");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(501);
    expect(res.headers.get("x-test")).toBe("1");
    expect(res.headers.getSetCookie()).toEqual(["error=1"]);

    t.errors = [];
  });

  it("throw number coerces to status", async () => {
    t.app.use(() => {
      throw 404;
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(404);
  });

  it("throw async number coerces to status", async () => {
    t.app.use(async () => {
      throw 500;
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
  });

  it("return number is unchanged", async () => {
    t.app.use(() => 404);
    const res = await t.fetch("/");
    expect(res.status).toBe(200);
    expect(await res.json()).toBe(404);
  });

  describe("non-Error throws", () => {
    it("throw object does not leak into the response body", async () => {
      t.app.use(() => {
        throw { secret: "db-password", message: "internal detail", status: 403 };
      });
      const res = await t.fetch("/");
      // A non-Error object is always an unhandled 500; nothing on it shapes the response
      expect(res.status).toBe(500);
      const body = await res.text();
      expect(body).not.toContain("db-password");
      expect(body).not.toContain("internal detail");
      expect(JSON.parse(body)).toMatchObject({ status: 500, unhandled: true });

      expect(t.errors[0].unhandled).toBe(true);
      expect(t.errors[0].cause).toMatchObject({ secret: "db-password" });
      t.errors = [];
    });

    // A non-Error object is never trusted to shape the response, not even via a `status` shorthand
    // (unlike `throw 404`). `status` / `statusCode` / `statusText` / `headers` are all dropped.
    it("status on a thrown object is never honored", async () => {
      const shapes = [
        { status: 403 },
        { statusCode: 429 },
        { status: 400, statusText: "Leaky Status Text" },
      ];
      for (const [i, shape] of shapes.entries()) {
        t.app.get(`/shape-${i}`, () => {
          throw shape;
        });
        const res = await t.fetch(`/shape-${i}`);
        expect(res.status).toBe(500);
        expect(res.statusText).not.toBe("Leaky Status Text");
      }
      t.errors = [];
    });

    it("throw async object does not leak into the response body", async () => {
      t.app.use(async () => {
        throw { secret: "db-password" };
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("db-password");
      t.errors = [];
    });

    it("throw string", async () => {
      t.app.use(() => {
        throw "not-an-error";
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("not-an-error");
      t.errors = [];
    });

    it("throw undefined", async () => {
      t.app.use(() => {
        throw undefined;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
      t.errors = [];
    });

    it("thrown object cannot forge response headers", async () => {
      t.app.use(() => {
        throw { headers: { "x-forged": "1" } };
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(res.headers.get("x-forged")).toBe(null);
      t.errors = [];
    });

    // `toError` must use the same `instanceof Error` check as `prepareResponse`. A broader check
    // (e.g. `Error.isError`) would pass this through, only for `prepareResponse` to reject it and
    // render it as a successful body again.
    it("cross-realm error is not rendered as a body", async () => {
      const foreign = runInNewContext(`new Error("cross-realm secret")`);
      t.app.use(() => {
        throw foreign;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.text()).not.toContain("cross-realm secret");
      t.errors = [];
    });

    // Fetch clients (ky, got) throw their own errors named `HTTPError`, without `status`, whose
    // message carries the upstream request URL. They must not pass as h3 `HTTPError`s.
    it("foreign error named HTTPError without status is unhandled", async () => {
      class UpstreamHTTPError extends Error {
        override name = "HTTPError";
      }
      const foreign = new UpstreamHTTPError("Request failed: GET https://internal/?token=secret");
      expect(HTTPError.isError(foreign)).toBe(false);
      t.app.use(() => {
        throw foreign;
      });
      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ unhandled: true, message: "HTTPError" });
      expect(t.errors[0].unhandled).toBe(true);
      t.errors = [];
    });

    it("onError receives the wrapped error", async () => {
      const onError = vi.fn();
      const app = new H3({ onError, silent: true });
      app.use(() => {
        throw { secret: "db-password" };
      });
      const res = await app.request("/");
      expect(res.status).toBe(500);
      expect(onError).toHaveBeenCalledTimes(1);
      const error = onError.mock.calls[0][0];
      expect(HTTPError.isError(error)).toBe(true);
      expect(error.unhandled).toBe(true);
      expect(error.cause).toMatchObject({ secret: "db-password" });
    });
  });

  // Regression for #1477: a synchronous throw while preparing the response (circular
  // `JSON.stringify`) must be routed through the same 500 pipeline as any other error,
  // not escape `fetch()` as a raw exception/rejection.
  describe("response preparation throws", () => {
    it("circular return value is rendered as a 500 instead of escaping fetch()", async () => {
      t.app.use(() => {
        const circular: any = {};
        circular.self = circular;
        return circular;
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
      t.errors = [];
    });

    it("thrown HTTPError with circular data is rendered as a 500 instead of escaping fetch() (no onError)", async () => {
      // With no `onError` configured, `errorResponse()`'s `JSON.stringify` runs
      // synchronously in the same pass as the throw (the async/onError branch is not
      // taken), so this exercises the raw synchronous-escape path directly.
      t.app.config.onError = undefined;
      t.app.use(() => {
        const data: any = {};
        data.self = data;
        throw new HTTPError({ status: 400, data });
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
    });
  });

  // Regression for #1503 (CodeRabbit): a synchronously-throwing `onError` hook must not
  // recurse infinitely. `Promise.resolve(onError(error, event))` evaluates the call before
  // wrapping it in a promise, so a sync throw there escaped `prepareResponse()` synchronously.
  // That was caught by `toResponse()`'s try/catch (added for #1477) and re-entered
  // `toResponse` with `nested` reset to `false` — calling the same throwing `onError` again,
  // forever (stack overflow instead of a normalized 500).
  it("a synchronously-throwing onError does not recurse infinitely", async () => {
    t.app.config.onError = () => {
      throw new Error("onError boom");
    };
    t.app.use(() => {
      throw new Error("handler boom");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(await res.json()).toMatchObject({ status: 500, unhandled: true });
  });

  // A value returned from `onError` replaces the response, so a value *thrown* by the hook must be
  // normalized through `toError()` first. Otherwise the two are indistinguishable and a non-Error
  // throw is rendered as a successful body: the hook's internals leak to the client and the failed
  // request reports 200.
  for (const [label, thrown] of [
    ["an object", { secret: "s3cr3t" }],
    ["a string", "leaked internal string"],
  ] as const) {
    it(`an onError throwing ${label} renders an unhandled 500, not a 200 body`, async () => {
      t.app.config.onError = () => {
        throw thrown;
      };
      t.app.use(() => {
        throw new Error("handler boom");
      });

      const res = await t.fetch("/");
      expect(res.status).toBe(500);
      const body = await res.json();
      expect(body).toMatchObject({ status: 500, unhandled: true });
      expect(JSON.stringify(body)).not.toContain("s3cr3t");
      expect(JSON.stringify(body)).not.toContain("leaked internal string");
    });
  }

  it("an onError throwing a number renders that status", async () => {
    t.app.config.onError = () => {
      throw 418;
    };
    t.app.use(() => {
      throw new Error("handler boom");
    });

    const res = await t.fetch("/");
    expect(res.status).toBe(418);
  });
});

describeMatrix("problem details (RFC 9457)", (t, { it, expect }) => {
  const PROBLEM = /^application\/problem\+json/;

  it("RF-01: renders status, title and detail without type/instance", async () => {
    t.app.get("/", () => {
      throw new HTTPError({ status: 404, message: "Usuário não encontrado" });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(404);
    const json = await res.json();
    expect(json).toMatchObject({
      status: 404,
      title: "Not Found",
      detail: "Usuário não encontrado",
    });
    expect("type" in json).toBe(false);
    expect("instance" in json).toBe(false);
  });

  it("RF-02: errors use problem+json, other responses stay json", async () => {
    t.app.get("/err", () => {
      throw HTTPError.status(400);
    });
    t.app.get("/ok", () => ({ ok: true }));
    expect((await t.fetch("/err")).headers.get("content-type")).toMatch(PROBLEM);
    expect((await t.fetch("/ok")).headers.get("content-type")).toBe(
      "application/json;charset=UTF-8",
    );
  });

  it("RF-03: type/instance on every constructor path", () => {
    const type = "https://example.com/probs/x";
    const instance = "/contas/42";
    for (const e of [
      new HTTPError({ status: 403, type, instance }),
      HTTPError.status(403, "Forbidden", { type, instance }),
      new HTTPError("msg", { status: 403, type, instance }),
      new HTTPError({ status: 403, cause: { type, instance } }),
    ]) {
      expect(e.type).toBe(type);
      expect(e.instance).toBe(instance);
    }
    const plain = new HTTPError({ status: 403 });
    expect(plain.type).toBeUndefined();
    expect(plain.instance).toBeUndefined();
    const bad = new HTTPError({ status: 403, cause: { type: {}, instance: 1 } });
    expect(bad.type).toBeUndefined();
    expect(bad.instance).toBeUndefined();
  });

  it("RF-04: serializes type/instance in body and toJSON", async () => {
    const type = "https://example.com/probs/x";
    const err = new HTTPError({ status: 403, message: "no", type, instance: "/a/1" });
    expect(err.toJSON()).toMatchObject({
      type,
      instance: "/a/1",
      status: 403,
      title: "Forbidden",
      detail: "no",
    });
    const bare = new HTTPError({ status: 403 }).toJSON();
    expect("type" in bare).toBe(false);
    expect("instance" in bare).toBe(false);
    t.app.get("/", () => {
      throw err;
    });
    expect(await (await t.fetch("/")).json()).toMatchObject({
      type,
      instance: "/a/1",
      status: 403,
    });
  });

  it("RF-05: data and body extensions cannot override standard members", async () => {
    t.app.get("/", () => {
      throw new HTTPError({
        status: 422,
        data: { campo: "email" },
        body: { codigo: "E42", status: 200, title: "x", type: "y" },
      });
    });
    const json = await (await t.fetch("/")).json();
    expect(json.data).toEqual({ campo: "email" });
    expect(json.codigo).toBe("E42");
    expect(json.status).toBe(422);
    expect(json.title).not.toBe("x");
    expect("type" in json).toBe(false);
  });

  it("RF-06: unhandled errors do not leak, debug adds stack", async () => {
    t.app.get("/", () => {
      throw new Error("segredo interno");
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(500);
    expect(res.headers.get("content-type")).toMatch(PROBLEM);
    const text = await res.text();
    expect(text).not.toContain("segredo interno");
    const json = JSON.parse(text);
    expect(json.stack).toBeUndefined();
    expect(json).toMatchObject({
      status: 500,
      title: "Internal Server Error",
      detail: "Internal Server Error",
    });

    t.app.config.debug = true;
    expect((await (await t.fetch("/")).json()).stack).toBeDefined();
  });

  it("RF-07: keeps status, statusText and headers; HEAD has no body", async () => {
    t.app.get("/", () => {
      throw new HTTPError({
        status: 401,
        statusText: "Unauthorized",
        headers: { "www-authenticate": "Basic" },
      });
    });
    const res = await t.fetch("/");
    expect(res.status).toBe(401);
    expect(res.statusText).toBe("Unauthorized");
    expect(res.headers.get("www-authenticate")).toBe("Basic");
    expect(await res.json()).toMatchObject({ status: 401, title: "Unauthorized" });
    const head = await t.fetch("/", { method: "HEAD" });
    expect(await head.text()).toBe("");
  });

  it("RF-08: all error paths use problem details", async () => {
    t.app.post("/validate", async (event) => {
      await readValidatedBody(event, () => ({ issues: [{ message: "bad" }] }));
    });
    t.app.post("/limit", async (event) => readBody(event), { middleware: [bodyLimit(4)] });
    t.app.get("/auth", async (event) => {
      await requireBasicAuth(event, { password: "x" });
    });
    const responses = [
